                stats = self.indexer.index(snapshot)
                self.store.update_job(job_id, "complete", stats=stats)
            except Exception as exc:
                self.store.update_job(
                    job_id,
                    "failed",
                    error=f"{type(exc).__name__}: {exc}",
                )
            finally:
                self.queue.task_done()

