    ranks = {str(k): int(v) for k, v in (data.get("ranks") or {}).items() if str(k) in keys}
    winner = data.get("winner")
    winner_s = str(winner) if winner in keys else None
    return winner_s, ranks, str(data.get("reason") or "")[:400]


