        root / ".ruff.toml"
    ).is_file()
    if ruff_configured:
        local = root / ".venv" / "bin" / "ruff"
        argv = (".venv/bin/ruff", "check", ".") if local.is_file() else (
            "python",
            "-m",
            "ruff",
            "check",
            ".",
        )
