        try:
            digest.update(path.read_bytes())
        except OSError:
            pass
    return RepoContract(
        repo_root=str(repo),
        languages=languages,
        known_test_roots=test_roots,
        commands=commands,
        configs=configs,
        fingerprint=digest.hexdigest(),
    )

