        if path.is_dir():
            continue
        if not path.is_file():
            raise ValueError(f"non-regular build input is forbidden: {relative}")
        digest.update(str(relative).encode("utf-8"))
        digest.update(b"\0")
        with path.open("rb") as handle:
            while chunk := handle.read(1024 * 1024):
                digest.update(chunk)
        digest.update(b"\0")
    return digest.hexdigest()


