        if value.tzinfo is None:
            raise LifecycleError("sandbox clock must return timezone-aware timestamps")
        return value

    @staticmethod
    def _safe_detail(exc: Exception) -> str:
        return str(exc).replace("\n", " ")[:1200] or type(exc).__name__

